-- M32 exact source, grants, handoff evidence and predecessor compatibility.
DO $delivery_lineage_verify$
DECLARE item record;actual text;
BEGIN
 IF NOT EXISTS(SELECT FROM forge_agent.schema_migrations WHERE version=32) THEN RETURN;END IF;
 IF NOT EXISTS(SELECT FROM forge_agent.schema_migrations WHERE version=32 AND name='observer_retry_lineage') THEN RAISE EXCEPTION 'Delivery lineage migration identity drift';END IF;
 SELECT jsonb_build_object('table',jsonb_build_array(c.relkind,c.relpersistence,pg_get_userbyid(c.relowner),c.relrowsecurity,c.relforcerowsecurity,c.relreplident,c.reloptions),'acl',to_jsonb(c.relacl),'columns',(SELECT jsonb_agg(jsonb_build_array(a.attnum,a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull,a.attidentity,a.attgenerated,a.attcollation::regcollation::text,pg_get_expr(d.adbin,d.adrelid),a.attacl) ORDER BY a.attnum) FROM pg_attribute a LEFT JOIN pg_attrdef d ON(d.adrelid,d.adnum)=(a.attrelid,a.attnum) WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped),'constraints',(SELECT jsonb_agg(jsonb_build_array(k.conname,k.contype,k.convalidated,k.condeferrable,k.condeferred,pg_get_constraintdef(k.oid,false)) ORDER BY k.conname) FROM pg_constraint k WHERE k.conrelid=c.oid),'indexes',(SELECT jsonb_agg(jsonb_build_array(ic.relname,i.indisvalid,i.indisready,pg_get_indexdef(i.indexrelid)) ORDER BY ic.relname) FROM pg_index i JOIN pg_class ic ON ic.oid=i.indexrelid WHERE i.indrelid=c.oid),'triggers',(SELECT jsonb_agg(jsonb_build_array(t.tgname,t.tgenabled,pg_get_triggerdef(t.oid,false)) ORDER BY t.tgname) FROM pg_trigger t WHERE t.tgrelid=c.oid AND NOT t.tgisinternal))::text INTO actual FROM pg_class c WHERE c.oid='forge_agent.delivery_lineage_handoffs'::regclass;
 IF actual IS DISTINCT FROM $shape1${"acl": ["forge_agent_owner=arwdDxt/forge_agent_owner"], "table": ["r", "p", "forge_agent_owner", false, false, "d", null], "columns": [[1, "handoff_id", "uuid", true, "", "", "-", "gen_random_uuid()", null], [2, "verification_id", "uuid", true, "", "", "-", null, null], [3, "post_merge_id", "uuid", true, "", "", "-", null, null], [4, "owner_id", "text", true, "", "", "\"default\"", null, null], [5, "project_alias", "text", true, "", "", "\"default\"", null, null], [6, "root_task_id", "uuid", true, "", "", "-", null, null], [7, "expected_lineage_id", "uuid", true, "", "", "-", null, null], [8, "provisional_lineage_id", "uuid", true, "", "", "-", null, null], [9, "reason", "text", true, "", "", "\"default\"", null, null], [10, "evidence", "jsonb", true, "", "", "-", null, null], [11, "created_at", "timestamp with time zone", true, "", "", "-", "clock_timestamp()", null]], "indexes": [["delivery_lineage_handoffs_pkey", true, true, "CREATE UNIQUE INDEX delivery_lineage_handoffs_pkey ON forge_agent.delivery_lineage_handoffs USING btree (handoff_id)"], ["delivery_lineage_handoffs_verification_id_expected_lineage__key", true, true, "CREATE UNIQUE INDEX delivery_lineage_handoffs_verification_id_expected_lineage__key ON forge_agent.delivery_lineage_handoffs USING btree (verification_id, expected_lineage_id, root_task_id)"]], "triggers": [["delivery_lineage_handoff_immutable", "O", "CREATE TRIGGER delivery_lineage_handoff_immutable BEFORE DELETE OR UPDATE ON forge_agent.delivery_lineage_handoffs FOR EACH ROW EXECUTE FUNCTION forge_agent.delivery_lineage_handoff_immutable()"]], "constraints": [["delivery_lineage_handoffs_evidence_check", "c", true, false, false, "CHECK ((jsonb_typeof(evidence) = 'object'::text))"], ["delivery_lineage_handoffs_expected_lineage_id_fkey", "f", true, false, false, "FOREIGN KEY (expected_lineage_id) REFERENCES forge_agent.delivery_lineages(lineage_id)"], ["delivery_lineage_handoffs_owner_id_project_alias_root_task_fkey", "f", true, false, false, "FOREIGN KEY (owner_id, project_alias, root_task_id) REFERENCES forge_agent.coding_tasks(owner_id, project_alias, id)"], ["delivery_lineage_handoffs_pkey", "p", true, false, false, "PRIMARY KEY (handoff_id)"], ["delivery_lineage_handoffs_post_merge_id_fkey", "f", true, false, false, "FOREIGN KEY (post_merge_id) REFERENCES forge_agent.post_merge_verifications(post_merge_id)"], ["delivery_lineage_handoffs_provisional_lineage_id_fkey", "f", true, false, false, "FOREIGN KEY (provisional_lineage_id) REFERENCES forge_agent.delivery_lineages(lineage_id)"], ["delivery_lineage_handoffs_reason_check", "c", true, false, false, "CHECK ((reason = ANY (ARRAY['repair_proof_missing'::text, 'provisional_lineage_used'::text])))"], ["delivery_lineage_handoffs_verification_id_expected_lineage__key", "u", true, false, false, "UNIQUE (verification_id, expected_lineage_id, root_task_id)"], ["delivery_lineage_handoffs_verification_id_fkey", "f", true, false, false, "FOREIGN KEY (verification_id) REFERENCES forge_agent.delivery_ledger(verification_id)"]]}$shape1$ THEN RAISE EXCEPTION 'Delivery lineage handoff table drift';END IF;
 FOR item IN SELECT * FROM(VALUES ('forge_agent._delivery_adopt_repair_lineage(uuid,uuid)','["forge_agent_owner", true, ["search_path=pg_catalog, pg_temp"], ["forge_agent_owner=X/forge_agent_owner"]]'),('forge_agent._delivery_lineage_blocked(text,text,uuid)','["forge_agent_owner", false, ["search_path=pg_catalog, pg_temp"], ["forge_agent_owner=X/forge_agent_owner"]]'),('forge_agent._delivery_lineage_legacy_source(oid,text)','["forge_agent_owner", false, ["search_path=pg_catalog, pg_temp"], ["forge_agent_owner=X/forge_agent_owner"]]'),('forge_agent._delivery_lineage_patches()','["forge_agent_owner", false, ["search_path=pg_catalog, pg_temp"], ["forge_agent_owner=X/forge_agent_owner"]]'),('forge_agent.delivery_lineage_handoff_immutable()','["forge_agent_owner", false, ["search_path=pg_catalog, pg_temp"], ["forge_agent_owner=X/forge_agent_owner"]]'),('forge_agent.delivery_register_post_merge(uuid)','["forge_agent_owner", true, ["search_path=pg_catalog, pg_temp"], ["forge_agent_owner=X/forge_agent_owner"]]'),('forge_agent.delivery_repair_admit(uuid,integer,uuid,text)','["forge_agent_owner", true, ["search_path=pg_catalog, pg_temp"], ["forge_agent=X/forge_agent_owner", "forge_agent_owner=X/forge_agent_owner"]]'),('forge_agent.delivery_repair_checkpoint(uuid,integer,uuid,jsonb)','["forge_agent_owner", true, ["search_path=pg_catalog, pg_temp"], ["forge_agent=X/forge_agent_owner", "forge_agent_owner=X/forge_agent_owner"]]'),('forge_agent.delivery_repair_claim(text)','["forge_agent_owner", true, ["search_path=pg_catalog, pg_temp"], ["forge_agent=X/forge_agent_owner", "forge_agent_owner=X/forge_agent_owner"]]')) expected(signature,shape) LOOP
 SELECT jsonb_build_array(pg_get_userbyid(p.proowner),p.prosecdef,p.proconfig,ARRAY(SELECT unnest(p.proacl::text[]) ORDER BY 1))::text INTO actual FROM pg_proc p WHERE p.oid=to_regprocedure(item.signature);
 IF actual IS DISTINCT FROM item.shape THEN RAISE EXCEPTION 'Delivery lineage authority drift: %',item.signature;END IF;
 END LOOP;
END;$delivery_lineage_verify$;
